 const [workflowRequests,setWorkflowRequests]=useState(()=>{const linkedTargets=['B2036','B1003','B2001','B2051'];return requests.map((x,i)=>({id:x[0],title:x[1],type:x[2],requester:x[3],status:x[4],date:x[5],targetBusinessId:linkedTargets[i],targetSubId:1,assignee:'PMO' /* TODO: 추후 담당자 배정 기능 필요 */,note:i===1?'\uBCF4\uC644 \uC0AC\uC720\uB97C \uC694\uCCAD\uC790\uC5D0\uAC8C \uC804\uB2EC\uD574\uC57C \uD569\uB2C8\uB2E4.':'\uAC80\uD1A0 \uB300\uAE30'}))});
 const [officialVersions,setOfficialVersions]=useState<VersionSnapshot[]>(()=>[{version:'v2.5',date:'2026-08-10 09:00',owner:'김서현',rows:cloneRows(items),status:'현재 활성'},{version:'v2.4',date:'2026-07-18 14:05',owner:'관리자 A',rows:cloneRows(itemsV24),status:'이전 버전'}]);
