 const loadMaster=React.useCallback(()=>{setMasterLoad({status:'loading'});fetchSnapshot().then(mapFetchOutcomeToState).then(state=>{setMasterLoad(state);if(state.status==='ready'){const m=state.meta;setOfficialVersions(prev=>prev.map((v,i)=>i===0?{...v,rows:state.items,version:(m&&m.versionNo&&m.versionNo.trim())?m.versionNo.trim():v.version,date:(m&&m.publishedAt)?m.publishedAt:v.date,owner:(m&&m.publisher)?m.publisher:v.owner}:v))}})},[]);
 useEffect(()=>{loadMaster()},[loadMaster]);
 const currentUserName='김서현';
