 const updateRequestStatus=(id:string,status:string)=>setWorkflowRequests(x=>x.map(r=>{if(r.id!==id)return r;const t=new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'});const note=status==='\uC2B9\uC778'?'\uC2B9\uC778 \uC644\uB8CC - SBF \uBC18\uC601 \uC791\uC5C5 \uB300\uAE30 ('+t+')':status==='SBF \uBC18\uC601 \uC911'?'SBF \uBC18\uC601 \uC791\uC5C5 \uC9C4\uD589 \uC911 ('+t+')':status==='SBF \uBC18\uC601 \uC644\uB8CC'?'SBF \uBC18\uC601 \uC644\uB8CC - Jira \uC0B0\uCD9C\uBB3C \uBC18\uC601 \uB300\uAE30 ('+t+')':`${status} - ${t}`;return {...r,status,note}}));
 const resubmitRevisionRequest=(id:string,memo:string)=>setWorkflowRequests(x=>x.map(r=>{if(r.id!==id)return r;const t=new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'});const prefix=r.status==='보완 요청'?'보완 수정 후 재요청':'반려 수정 후 재요청';return {...r,status:'요청 접수',note:prefix+' - '+(memo.trim()||'수정 내용 입력')+' ('+t+')'}}));
