 const downloadCsv=(requestedVersion=version,useFilters=false)=>{const versionData=officialVersions.find(v=>v.version===requestedVersion)?.rows??itemsV24;const exportItems=useFilters?filtered:versionData;const headers=['SBF \uBC84\uC804',...iaHeaders];const quote=(v:string|number)=>`"${String(v).replaceAll('"','""')}"`;const lines=exportItems.map(x=>[requestedVersion,...x.raw].map(quote).join(','));const blob=new Blob(['\uFEFF'+[headers.map(quote).join(','),...lines].join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`SBF_${requestedVersion}_${new Date().toISOString().slice(0,10)}.csv`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);notify(`${requestedVersion} ${exportItems.length}\uAC74\uC744 CSV\uB85C \uB0B4\uB824\uBC1B\uC558\uC2B5\uB2C8\uB2E4.`)};
 const requestBadge=(item:Item)=>{const hit=workflowRequests.find(r=>requestMatchesItem(r,item));if(!hit)return '';if(hit.type.includes('\uC0AD\uC81C'))return '\uC0AD\uC81C \uB300\uAE30';return hit.status==='\uC694\uCCAD \uC811\uC218'?'\uBCC0\uACBD\uC694\uCCAD \uC811\uC218':hit.status==='\uAC80\uD1A0 \uC911'?'\uAC80\uD1A0 \uC911':hit.status==='\uBCF4\uC644 \uC694\uCCAD'?'\uBCF4\uC644 \uD544\uC694':hit.status==='SBF \uBC18\uC601 \uC911'?'\uC218\uC815 \uBC18\uC601 \uC911':hit.status==='SBF \uBC18\uC601 \uC644\uB8CC'||hit.status==='\uC791\uC5C5 \uC644\uB8CC'?'\uBC18\uC601 \uC644\uB8CC':hit.status==='\uBC18\uB824'?'\uBC18\uB824':hit.status};
